    usernames = []

    for name in full_names:
        base = name.lower().replace(" ", "")
        if base not in counts:
            counts[base] = 1
            usernames.append(base)
        else:
            counts[base] += 1
            usernames.append(f"{base}{counts[base]}")

    return usernames
